using System.Diagnostics;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Engine.Chess.Board;
using Engine.Chess.Core;
using Engine.Chess.Evaluation;
using Engine.Chess.Notation;

namespace Engine.Jev.Host;

public sealed record JevMoveDecision(string Uci, double Confidence, int ElapsedMilliseconds,
    int InputTokens, int OutputTokens);

/// <summary>Asks Jev to choose from moves generated by the chess engine.</summary>
public sealed class JevDecisionService(HttpClient http, string apiKey, string model = "jev-latest") {
    public async Task<JevMoveDecision> ChooseAsync(Position position, CancellationToken cancellation = default) {
        MoveList legal = position.LegalMoves();
        if (legal.Count == 0) throw new InvalidOperationException("The position has no legal moves.");

        var criteria = new Dictionary<string, string>(legal.Count);
        for (int i = 0; i < legal.Count; i++) {
            Move move = legal[i];
            criteria.Add(move.ToUci(), San.ToSan(position, move));
        }

        var request = new {
            model,
            state = new {
                fen = position.ToFen(),
                board = BoardText(position),
                side_to_move = position.SideToMove.ToString(),
                material_balance_white_centipawns = Evaluator.MaterialBalance(position),
                notation = "The criteria keys are legal UCI moves; their descriptions are SAN moves.",
            },
            questions = new Dictionary<string, object> {
                ["move"] = new {
                    type = "choice",
                    instructions = "Choose the legal move most likely to improve the side-to-move's chance of winning the game. Consider the chess position and tactical safety.",
                    criteria,
                },
            },
        };

        using var message = new HttpRequestMessage(HttpMethod.Post, "v1/systemone") {
            Content = JsonContent.Create(request),
        };
        message.Headers.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);

        var watch = Stopwatch.StartNew();
        using HttpResponseMessage response = await http.SendAsync(message, cancellation);
        if (!response.IsSuccessStatusCode) {
            throw new HttpRequestException($"Jev API returned HTTP {(int)response.StatusCode}.");
        }

        using JsonDocument body = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellation), cancellationToken: cancellation);
        JsonElement root = body.RootElement;
        if (!root.TryGetProperty("answers", out JsonElement answers) ||
            !answers.TryGetProperty("move", out JsonElement answer) ||
            !answer.TryGetProperty("type", out JsonElement type) || type.GetString() != "choice" ||
            !answer.TryGetProperty("choice", out JsonElement selected) ||
            selected.GetString() is not string uci || !criteria.ContainsKey(uci)) {
            throw new InvalidDataException("Jev returned a move outside the legal choices.");
        }

        double confidence = answer.TryGetProperty("confidence", out JsonElement confidenceValue)
            ? confidenceValue.GetDouble() : 0;
        JsonElement usage = root.GetProperty("usage");
        return new JevMoveDecision(uci, confidence, (int)watch.ElapsedMilliseconds,
            usage.GetProperty("input_tokens").GetInt32(),
            usage.GetProperty("output_tokens").GetInt32());
    }

    private static string BoardText(Position position) {
        var rows = new string[8];
        for (int rank = 7; rank >= 0; rank--) {
            var squares = new char[8];
            for (int file = 0; file < 8; file++) {
                Piece piece = position.PieceAt(Squares.From(file, rank));
                squares[file] = piece == Piece.None ? '.' : piece.ToChar();
            }
            rows[7 - rank] = new string(squares);
        }
        return string.Join('\n', rows);
    }
}
